# fichier tests/reseau.tftest.hcl
variables {
  cidr = "10.0.0.0/16"
}

run "cree_le_bon_cidr" {
  command = plan            # test rapide, sans rien créer
  assert {
    condition     = aws_vpc.main.cidr_block == "10.0.0.0/16"
    error_message = "Le CIDR du VPC est incorrect"
  }
}
# terraform test  -> exécute tous les *.tftest.hcl

# tests/module.tftest.hcl
mock_provider "aws" {}          # ne contacte pas le cloud

run "structure_correcte" {
  command = plan
  # asserter sur la logique, sans créer de ressources
  assert {
    condition     = length(aws_subnet.this) == 3
    error_message = "Il devrait y avoir 3 sous-réseaux"
  }
}
# override_resource / override_data : fournir des valeurs déterministes
